        const a = h2("a", {
          href: URL.createObjectURL(blob),
          download: suggestFilename(tr, fmt2)
        });
        document.body.appendChild(a);
        a.click();
        later(() => {
          URL.revokeObjectURL(a.href);
          a.remove();
        }, 1500);
